// Signature: (pidfd, signal, siginfo, flags=0)
int pidfd_send_signal(int pidfd, int sig,
                      const siginfo_t *info, unsigned int flags);

int pfd = 3;

// Send standard SIGTERM (info=NULL, flags=0)
int ret = pidfd_send_signal(pfd, SIGTERM, NULL, 0);

// Send Realtime Signal with custom data
siginfo_t si = { .si_code = SI_USER };
si.si_value.sival_int = 101;
si.si_signo = SIGRTMIN + 5;

pidfd_send_signal(pfd, SIGRTMIN + 5, &si, 0);
